PIE 结束或关卡切换时，下面这个定时回调仍在跑，日志里出现一批对已销毁 Actor 的无效调用。请指出还缺哪一层判断、为什么，并给出修正要点：

```cpp
void AMyTurret::BeginPlay()
{
    Super::BeginPlay();
    GetWorld()->GetTimerManager().SetTimer(
        PollTimer, this, &AMyTurret::PollTarget, 0.5f, true);
}

void AMyTurret::PollTarget()
{
    AActor* Target = CachedTarget.Get();
    if (!IsValid(Target) || Target->IsActorBeingDestroyed())
    {
        CachedTarget.Reset();
        return;
    }
    if (MyMesh && MyMesh->IsVisible())
    {
        Target->SetActorLocation(GetActorLocation());
    }
}
```

下面的定时器用 lambda 捕获裸 this，且 EndPlay 只解绑了委托，组件销毁后偶发崩溃。请指出两处问题并给出 UE5 的修法：

```cpp
void UMyListenerComponent::BeginPlay()
{
    Super::BeginPlay();
    if (UMyEventManager* Mgr = GetWorld()->GetSubsystem<UMyEventManager>())
    {
        Mgr->OnWaveStart.AddUObject(this, &UMyListenerComponent::HandleWaveStart);
    }
    FTimerDelegate Delegate = FTimerDelegate::CreateLambda([this]()
    {
        CachedTarget.Reset();
        RefreshUI();
    });
    GetWorld()->GetTimerManager().SetTimer(PollTimer, Delegate, 1.f, true);
}

void UMyListenerComponent::EndPlay(const EEndPlayReason::Type Reason)
{
    if (UMyEventManager* Mgr = GetWorld()->GetSubsystem<UMyEventManager>())
    {
        Mgr->OnWaveStart.RemoveAll(this);
    }
    Super::EndPlay(Reason);   // 没有清理 PollTimer
}
```

